SET NUMERIC_ROUNDABORT OFF
GO
SET ANSI_PADDING, ANSI_WARNINGS, CONCAT_NULL_YIELDS_NULL, ARITHABORT, QUOTED_IDENTIFIER, ANSI_NULLS ON
GO
SET XACT_ABORT ON
GO
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE
GO
BEGIN TRANSACTION
GO
IF @@ERROR <> 0 SET NOEXEC ON
GO
PRINT N'Altering [tompit].[worker]'
GO
IF @@ERROR <> 0 SET NOEXEC ON
GO
ALTER TABLE [tompit].[worker] ADD
[retry_interval] [int] NOT NULL CONSTRAINT [DF_worker_retry_interval] DEFAULT ((10)),
[disable_treshold] [int] NOT NULL CONSTRAINT [DF_worker_disable_treshold] DEFAULT ((3))
GO
IF @@ERROR <> 0 SET NOEXEC ON
GO
PRINT N'Altering [tompit].[worker_ins]'
GO
ALTER PROCEDURE [tompit].[worker_ins]
	@start_time smalldatetime  = NULL,
	@end_time smalldatetime = NULL,
	@interval_type int,
	@interval_value int,
	@start_date smalldatetime = NULL,
	@end_date smalldatetime = NULL,
	@limit int,
	@status int,
	@day_of_month int,
	@last_run datetime = NULL,
	@last_complete datetime = NULL,
	@next_run datetime2(7) = NULL,
	@day_mode int,
	@month_mode int,
	@year_mode int,
	@run_count bigint,
	@month_number int,
	@end_mode int,
	@interval_counter int,
	@month_part int,
	@elapsed int,
	@weekdays int,
	@fail_count int,
	@worker uniqueidentifier,
	@logging bit,
	@kind int,
	@retry_interval int,
	@disable_treshold int
AS
BEGIN
	SET NOCOUNT ON;

	INSERT tompit.worker (start_time, end_time, interval_type, interval_value, start_date, end_date, limit, status, day_of_month,
		last_run, last_complete, next_run, day_mode, month_mode, year_mode, run_count, month_number, end_mode, interval_counter,
		month_part, elapsed, weekdays, fail_count, worker, logging, kind, retry_interval, disable_treshold)
	VALUES (@start_time, @end_time, @interval_type, @interval_value, @start_date, @end_date, @limit, @status, @day_of_month,
		@last_run, @last_complete, @next_run, @day_mode, @month_mode, @year_mode, @run_count, @month_number, @end_mode, @interval_counter,
		@month_part, @elapsed, @weekdays, @fail_count, @worker, @logging, @kind, @retry_interval, @disable_treshold);
END
GO
IF @@ERROR <> 0 SET NOEXEC ON
GO
PRINT N'Altering [tompit].[worker_upd]'
GO
ALTER PROCEDURE [tompit].[worker_upd]
	@id int,
	@start_time smalldatetime  = NULL,
	@end_time smalldatetime = NULL,
	@interval_type int,
	@interval_value int,
	@start_date smalldatetime = NULL,
	@end_date smalldatetime = NULL,
	@limit int,
	@status int,
	@day_of_month int,
	@last_run datetime = NULL,
	@last_complete datetime = NULL,
	@next_run datetime2(7) = NULL,
	@day_mode int,
	@month_mode int,
	@year_mode int,
	@run_count bigint,
	@month_number int,
	@end_mode int,
	@interval_counter int,
	@month_part int,
	@elapsed int,
	@weekdays int,
	@fail_count int,
	@logging bit,
	@state uniqueidentifier = NULL,
	@retry_interval int,
	@disable_treshold int
AS
BEGIN
	SET NOCOUNT ON;

	UPDATE tompit.worker SET
		start_time = @start_time, 
		end_time = @end_time, 
		interval_type = @interval_type, 
		interval_value = @interval_value, 
		start_date = @start_date, 
		end_date = @end_date, 
		limit = @limit, 
		status = @status, 
		day_of_month = @day_of_month,
		last_run = @last_run, 
		last_complete = @last_complete, 
		next_run = @next_run, 
		day_mode = @day_mode, 
		month_mode = @month_mode, 
		year_mode = @year_mode, 
		run_count = @run_count, 
		month_number = @month_number, 
		end_mode = @end_mode, 
		interval_counter = @interval_counter,
		month_part = @month_part, 
		elapsed = @elapsed, 
		weekdays = @weekdays, 
		fail_count = @fail_count, 
		logging = @logging,
		state = @state,
		retry_interval = @retry_interval,
		disable_treshold = @disable_treshold
	WHERE id = @id;
END
GO
IF @@ERROR <> 0 SET NOEXEC ON
GO
COMMIT TRANSACTION
GO
IF @@ERROR <> 0 SET NOEXEC ON
GO
DECLARE @Success AS BIT
SET @Success = 1
SET NOEXEC OFF
IF (@Success = 1) PRINT 'The database update succeeded'
ELSE BEGIN
	IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION
	PRINT 'The database update failed'
END
GO
